<script lang="ts">import {publicHref,publicLabels,type PublicRow} from '$lib/content/public';let {items,variant='list'}:{items:PublicRow[];variant?:'list'|'featured'|'projects'}=$props();const date=(value:string|Date)=>new Date(value).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'});const updated=(item:PublicRow)=>!!item.update_at&&new Date(item.update_at).getTime()>new Date(item.first_published_at).getTime();const statusLabel=(value:unknown)=>({completed:'已完成','in-progress':'进行中',paused:'暂停',stopped:'已停止'})[String(value)]??'';</script>
{#if !items.length}<div class="empty"><span aria-hidden="true">✦</span><p>暂无公开内容。</p></div>{:else}<ul class={variant}>{#each items as item}<li>{#if variant==='projects'}<div class="visual">{#if typeof item.payload.cover==='string'&&item.payload.cover}<img src={`/media/public/${item.payload.cover}`} alt={item.title}/>{:else}<span aria-hidden="true">{item.title?.slice(0,1)||'作'}</span><small>封面待补</small>{/if}</div>{/if}<div class="item-copy"><p class="meta"><span class="type">{publicLabels[item.type]}</span><span aria-hidden="true">·</span>{updated(item)?'更新于 ':''}{date(item.update_at??item.first_published_at??item.published_at)}</p><a class="item-title" href={publicHref(item.type,item.slug)}><h3>{item.title||item.summary||publicLabels[item.type]}</h3></a>{#if item.summary}<p class="summary">{item.summary}</p>{/if}{#if variant==='projects'}<p class="project-status">{statusLabel(item.payload.projectStatus)}</p>{/if}</div><a class="item-arrow" href={publicHref(item.type,item.slug)} aria-label={`阅读：${item.title||item.summary||publicLabels[item.type]}`}>↗</a></li>{/each}</ul>{/if}
<style>
 ul{list-style:none;padding:0;margin:0}li{position:relative;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:16px;padding:22px 0;border-bottom:1px solid var(--line);min-width:0}li:first-child{border-top:1px solid var(--line)}.item-copy{min-width:0}.meta{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:0 0 7px;color:var(--muted);font:13px/1.4 'JetBrains Mono',monospace}.type{color:var(--primary);font-weight:700}.item-title{color:var(--text);text-decoration:none}.item-title h3{margin:0;font-size:20px;line-height:1.4}.item-title:hover h3{color:var(--primary)}.summary{margin:8px 0 0;color:var(--muted);display:-webkit-box;display:box;-webkit-line-clamp:2;line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.item-arrow{align-self:center;display:grid;place-items:center;width:40px;height:40px;border:1px solid var(--line);border-radius:50%;color:var(--muted);text-decoration:none;transition:all .18s ease}.item-arrow:hover{border-color:var(--primary);color:var(--primary);background:var(--soft)}.project-status{display:inline-flex;margin:12px 0 0;padding:4px 9px;border-radius:999px;background:var(--soft);color:var(--focus);font-size:13px}.empty{display:grid;place-items:center;gap:4px;padding:44px 20px;border:1px dashed var(--border);border-radius:var(--radius-md);color:var(--muted)}.empty span{color:var(--primary);font-size:22px}.empty p{margin:0}.featured{display:grid;grid-template-columns:1.35fr 1fr;gap:0 32px;border-top:1px solid var(--line)}.featured li{padding:24px 0}.featured li:first-child{grid-row:span 2;padding:32px;background:var(--soft);border:0;border-radius:0 0 var(--radius-md) var(--radius-md);margin-right:0}.featured li:first-child .item-title h3{font-size:30px}.projects{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;border:0}.projects li{display:flex;flex-direction:column;gap:18px;padding:0;border:1px solid var(--line);border-radius:var(--radius-md);overflow:hidden;background:var(--surface);box-shadow:var(--shadow-sm)}.projects li:first-child{border-top:1px solid var(--line)}.projects .item-copy{padding:0 20px 20px}.projects .item-arrow{position:absolute;right:16px;bottom:18px;background:var(--surface)}.visual{aspect-ratio:16/10;background:linear-gradient(135deg,var(--soft),var(--soft-strong));display:grid;place-items:center;position:relative;overflow:hidden;color:var(--primary);font-size:48px;font-weight:800}.visual img{width:100%;height:100%;object-fit:cover}.visual small{position:absolute;bottom:10px;left:12px;padding:3px 7px;border-radius:5px;background:rgba(255,255,255,.8);color:var(--muted);font-size:11px}.projects .meta{margin-bottom:8px}
 @media(max-width:767px){.featured,.projects{display:block}.featured li:first-child{padding:22px;border-radius:0}.projects li{margin-bottom:14px}.projects .item-copy{padding:0 16px 18px}.item-title h3{font-size:19px}}
</style>
